    explanation: "【要点】無症候性細菌尿は原則として治療しない。抗菌薬治療が推奨される代表的例外は妊婦と、粘膜出血を伴う泌尿器処置の前である。\n【理由】妊娠では腎盂腎炎・早産リスクの低減、侵襲的泌尿器処置前では菌血症予防の観点で治療の便益が示されている。それ以外(高齢者、施設入所者、糖尿病、カテーテル留置)では、症状がなければ治療は予後を改善せず、耐性菌やC. difficile感染のリスクを増やす。\n【実践】高齢者の非特異的症状だけで尿培養陽性=治療としないことが、抗菌薬適正使用の要点。\n【誤答】高齢者一般・カテーテル留置全例・糖尿病一般は治療対象ではない。",
