    question: "58歳、真の治療抵抗性高血圧。ACE阻害薬/ARB・カルシウム拮抗薬・サイアザイド系利尿薬を最大耐用量で用い、スピロノラクトンを追加してもなお診察室血圧が目標未達。アドヒアランス不良や二次性高血圧は評価済みである。近年承認され、この段階の上乗せ治療の選択肢になりうる薬剤はどれか。",
    options: ["α遮断薬(ドキサゾシン)への一本化", "経口ミノキシジルの少量追加", "ループ利尿薬をサイアザイドの代わりに常用へ変更", "デュアルエンドセリン受容体拮抗薬アプロシテンタンの追加"],
    correct: 3,
    explanation: "【要点】標準4剤(RAS阻害薬・CCB・利尿薬・MRA)でも未達の真の治療抵抗性高血圧では、2024年に承認されたデュアルエンドセリン受容体拮抗薬アプロシテンタンが追加の選択肢となる。\n【背景/エビデンス】第3相PRECISION試験(730例、amlodipine/valsartan/HCTZの固定併用下)で、アプロシテンタン12.5/25mgは4週で診察室・24時間血圧をプラセボより有意に低下させ、40週まで効果が持続した。主な有害事象は用量依存性の軽〜中等度の浮腫/体液貯留。\n【臨床応用/注意】体液貯留・貧血に留意し、催奇形性の懸念から妊娠可能女性では避ける。心不全での体液管理に注意し、導入前にアドヒアランスと二次性要因の評価を済ませておく。\n【誤答】ミノキシジル・ループ利尿薬への変更・α遮断薬はいずれも抵抗例で用いられうるが、本問で問われた『近年承認された新規機序の薬』ではない。",
