    question: "発作性の高血圧・動悸・頭痛・発汗を呈し褐色細胞腫を疑う患者で、スクリーニング検査として感度が高く第一に選択されるのはどれか。",
    options: ["血漿遊離メタネフリン分画または尿中メタネフリン分画の測定", "血中カテコラミン(アドレナリン・ノルアドレナリン)の単回測定", "副腎CTを先行し腫瘍が見つかれば診断を確定とする", "デキサメタゾン抑制試験"],
    correct: 0,
    explanation: "【要点】褐色細胞腫のスクリーニングは、カテコラミン代謝物である血漿遊離メタネフリン分画または尿中メタネフリン分画の測定が感度が高く第一選択となる。\n【背景/エビデンス】カテコラミンは緊張や運動で変動し特異度が低いが、メタネフリン分画は腫瘍内で持続的に産生されるため感度約95%以上と高い。随時尿メタネフリン/ノルメタネフリンが正常上限の3倍以上なら強く疑う。生化学的に陽性を確認してから画像(CT/MRI、必要に応じMIBGシンチ)で局在診断する。\n【臨床応用/注意】三環系抗うつ薬やαβ遮断薬など偽陽性をきたす薬剤・状況に注意する。手術前はα遮断薬で十分に前処置し高血圧クリーゼを予防する。\n【誤答】単回カテコラミンは変動が大きく不適。画像先行は偶発腫との区別ができず、デキサメタゾン抑制試験はCushing症候群の検査で本症のスクリーニングではない。",
    source: { title: "褐色細胞腫診断：血中遊離メタネフリン２分画測定(日本アフェレシス学会雑誌 J-STAGE)", url: "https://www.jstage.jst.go.jp/article/jaesjsts/29/2/29_101/_html/-char/ja/" },
