    added: "2026-07-26",
    question: "ビタミンB12欠乏症の臨床像について正しいものはどれか。",
    options: ["大球性(巨赤芽球性)貧血をきたす", "末梢血は小球性低色素性貧血を呈するのが特徴である", "後索・側索が障害され亜急性連合性脊髄変性症を生じうる", "神経症状は必ず貧血の進行後に出現し、貧血がなければ生じない"],
    correct: [0, 2],
    explanation: "【要点】ビタミンB12欠乏は大球性(巨赤芽球性)貧血をきたし、後索・側索が障害される亜急性連合性脊髄変性症など神経症状を生じうる。\n【背景/エビデンス】B12はメチルマロニルCoAムターゼやメチオニン合成の補酵素で、欠乏によりDNA合成障害(巨赤芽球性変化)と髄鞘障害が起こる。血清メチルマロン酸・ホモシステインの上昇が早期診断に有用。深部覚(振動覚・位置覚)低下、腱反射低下、失調、認知・精神症状などを呈する。\n【臨床応用/注意】神経症状は不可逆化しうるため早期補充が重要。悪性貧血・胃切除後・厳格な菜食・メトホルミン長期使用などが原因となる。葉酸単独投与は貧血を改善しても神経障害を進行させうる点に注意する。\n【誤答】小球性低色素性は鉄欠乏の所見で本症は大球性。神経症状は貧血の重症度と相関せず、貧血を欠く例でも出現しうるため『必ず貧血後』は誤り。",
    source: { title: "ビタミンB12欠乏症(MSDマニュアル プロフェッショナル版)", url: "https://www.msdmanuals.com/ja-jp/professional/09-%E6%A0%84%E9%A4%8A%E9%9A%9C%E5%AE%B3/%E3%83%93%E3%82%BF%E3%83%9F%E3%83%B3%E6%AC%A0%E4%B9%8F%E7%97%87-%E4%BE%9D%E5%AD%98%E7%97%87-%E3%81%8A%E3%82%88%E3%81%B3%E4%B8%AD%E6%AF%92/%E3%83%93%E3%82%BF%E3%83%9F%E3%83%B3b12%E6%AC%A0%E4%B9%8F%E7%97%87" },
    tags: ["血液", "神経", "ビタミンB12欠乏", "複数選択"]
