    question: "経皮的冠動脈形成術後の急性心筋梗塞患者にスピロノラクトンを投与したCLEAR SYNERGY(OASIS-9)試験のスピロノラクトン群の主要結果はどれか。",
    options: ["主要複合アウトカムをプラセボ比で有意に減少させた", "心血管死・新規/増悪心不全等の複合をプラセボ比で有意には減少させなかった", "総死亡をプラセボ比で約30%減少させた", "高カリウム血症は減少し有効性も増強した"],
    correct: 1,
    explanation: "【要点】CLEAR SYNERGY(OASIS-9)のスピロノラクトン群では、心血管死または新規/増悪心不全の複合、および心筋梗塞・脳卒中等を含む複合アウトカムを、プラセボと比べ有意には減少させなかった。\n【背景/エビデンス】NEJM 2024。PCI後72時間以内の心筋梗塞7,062例を2×2要因デザインでコルヒチン/スピロノラクトンとプラセボに割付けた大規模RCT。EF低下例を主対象としたEPHESUS等と異なり、EFを問わない広い集団への『ルーチン投与』を検証した点が特徴。\n【臨床応用/注意】本結果は全MI患者への一律のMRA投与を支持しない。一方、心不全合併やEF低下例へのMRA適応(既存エビデンス)は別途維持される。導入時は高カリウム血症・腎機能の監視が必要。\n【誤答】有意減少・総死亡30%減・有効性増強は、いずれも試験結果と異なる。同試験のコルヒチン群も主要アウトカムは中立だった。",
    source: { title: "Routine Spironolactone in Acute Myocardial Infarction (CLEAR SYNERGY/OASIS-9, NEJM)", url: "https://www.nejm.org/doi/full/10.1056/NEJMoa2405923" },
    tags: ["循環器", "心筋梗塞", "スピロノラクトン", "MRA"]
