    correct: 2,
    explanation: "【要点】HIF-PH阻害薬は経口の腎性貧血治療薬で、低酸素誘導因子(HIF)を安定化させ内因性エリスロポエチン産生と鉄の吸収・利用を促進する。\n【背景/エビデンス】ロキサデュスタット、ダプロデュスタット等が保存期・透析期CKDで承認され、ESA製剤に非劣性の貧血改善を示した。ESA未治療の保存期CKDでは低用量から開始し、Hb値と治療歴に応じて用量を調整する。\n【臨床応用/注意】投与前に血栓塞栓症(脳梗塞・心筋梗塞・肺塞栓)のリスクを評価し、鉄欠乏を補正しつつ管理する。目標Hbはおおむね11〜13g/dL程度とし過度な上昇を避ける。網膜症・悪性腫瘍への影響にも留意する。\n【誤答】HIF-PH阻害薬は経口薬であり注射ではない。血栓リスク評価と鉄管理はいずれも必要。Hb16g/dL以上を目標とする管理は過剰で推奨されない。",
