    explanation: "【要点】症候性多発性骨髄腫のCRAB基準は高カルシウム血症(C)、腎障害(R)、貧血(A)、溶骨性骨病変(B)からなり、いずれか1つ以上の臓器障害があると治療適応となる。\n【背景/エビデンス】現行のIMWG基準ではCRABに加え、骨髄形質細胞≧60%、血清遊離軽鎖比≧100、MRIで2か所以上の巣状病変(SLiM)のいずれかでも症候性と診断する。Mタンパクや骨髄クローナル形質細胞の証明が前提となる。\n【臨床応用/注意】具体的にはCa>11mg/dL、Cr>2mg/dLまたはCcr<40、Hb<10g/dL、溶骨性病変などが基準。骨病変評価には全身CT/MRI/PETを用いる。\n【誤答】反応性血小板増多や好中球増多はCRABに含まれず、骨髄腫に特徴的な所見でもない。",
