    correct: 3,
    explanation: "【要点】2025年ILAE発作分類は、焦点・全般・起始不明・分類不能の4つの主要クラスを維持しつつ、クラス名から『起始(onset)』の語を外した。\n【背景/エビデンス】全般発作でも焦点起始を示唆する所見があるとの知見を踏まえた改訂で、修正Delphi法(2/3超の合意)で策定された。意識は認識(awareness)と反応性(responsiveness)の両面で操作的に評価し、翻訳や反応性評価の欠落といった2017年版の課題に対処した。運動・非運動の二分は観察可能・不可能へ拡張された。全21発作型からなり、基本版は一次診療・資源限定環境でも使えるよう配慮されている。\n【臨床応用/注意】問診や目撃情報から発作型を系統的に記述し、抗発作薬選択や専門医紹介の判断に活かす。分類は病歴で更新しうる。\n【誤答】主要クラスを2つに簡略化した、認識のみで評価する、運動・非運動を廃止し観察可能性の区別を導入しなかった、はいずれも改訂内容と異なる。",
