    explanation: "【要点】GCAを強く疑う場合は確定検査の結果を待たずにグルココルチコイド(GC)を速やかに開始し、疑い例はおおむね24時間以内に専門医へ紹介する。ただし『一律に緊急でGC』ではなく、疑いの強さと頭蓋虚血性合併症の有無で緊急度・用量・投与経路を判断する。\n【背景/エビデンス】2025年 EULAR推奨(PMRと一次性大型血管炎を統合、4原則・12推奨・2質指標)は、強い臨床的疑いがあれば確定検査を待たずGCを開始するとしつつ、視力障害・脳卒中などの頭蓋虚血性合併症があれば高用量(必要時はメチルプレドニゾロン静注パルス0.25〜1 g/日×3〜5日)、合併症のない例では経口プレドニゾロン40〜60 mg/日を目安とする。ファストトラック外来は失明を約19〜27%から12〜13%へ減らし診断までの日数を短縮し、超音波等で48時間以内の診断・治療も可能とする。\n【臨床応用/注意】迅速な画像・専門医評価が得られる体制では、GC開始と確定診断はほぼ同時に進められる。GC開始前に可能な範囲で検体・画像を確保しつつ治療を遅らせない。長期GCに伴う骨粗鬆症・感染・血糖悪化をモニタリングする。\n【誤答】確定検査までGCを待つ、一次診療のみで経過観察し紹介しない、はいずれも失明等のリスクを高めこの文脈で不適切である。",
