    explanation: "【要点】REGENCY試験では、標準治療にオビヌツズマブを上乗せすると76週時点の完全腎奏効(CRR)の達成割合がプラセボより有意に高かった。\n【背景/エビデンス】生検で確認した活動性ループス腎炎の成人271例を1:1でオビヌツズマブ群かプラセボ群に割付けた第3相試験(NEJM 2025)。主要評価項目のCRR(尿蛋白/クレアチニン比<0.5等で定義)は76週でオビヌツズマブ群46.4% vs プラセボ群33.1%と有意差を示した。B細胞をより深く枯渇させる第II型抗CD20抗体で、既存の免疫抑制へ上乗せする位置づけ。感染やCOVID-19関連事象は同群でやや多かった。\n【臨床応用/注意】重症・難治のループス腎炎で腎予後改善を狙う選択肢となりうるが、感染対策やワクチン接種、B細胞枯渇に伴うリスク管理を要する。適応は個別の腎病型・活動性と併存症を踏まえ専門医と判断する。\n【誤答】有意差なし・腎機能悪化・軽症例限定は、いずれも試験結果と異なる。",
