    options: ["持続的血小板反応の達成割合はプラセボと有意差がなかった", "血小板数をむしろ低下させ、出血を増加させた", "有効性は脾摘の既往がある患者に限られた", "プラセボに比べ持続的血小板反応の達成割合が有意に高かった"],
