    question: "腹痛と便通異常を訴える成人に対する過敏性腸症候群(IBS)の診断について、支持される記述はどれか。",
    options: ["発熱や体重減少などの警告徴候があっても、Rome IV基準を満たせばそのままIBSと診断してよい", "確定診断には全例で大腸内視鏡が必須であり、施行しなければIBSと診断してはならない", "便形状の評価は不要で、腹痛の頻度のみを用いてサブタイプを分類する", "週1回以上の腹痛と便形状・排便頻度の変化を軸に、Bristol便形状スケールでサブタイプを分類し、器質的疾患を除外する"],
    correct: 3,
    explanation: "【要点】IBSは繰り返す腹痛と便通変化を診断軸とし、Rome IV基準で症状とサブタイプを分類する。\n【背景/エビデンス】週1回以上の腹痛に便形状・排便頻度の変化を伴うことが中心で、Bristol便形状スケールを用いて下痢型・便秘型などに分類する。脳腸相関や感染性腸炎後IBS(PI-IBS)など多因子の病態を意識して評価する。\n【臨床応用/注意】大腸癌・炎症性腸疾患・内分泌疾患などの器質的疾患の除外が最優先で、サブタイプに応じた薬物選択を行う。\n【誤答】警告徴候があれば精査が必要でそのままIBSとはできない。内視鏡は一律必須ではなくリスクに応じて判断する。腹痛頻度のみでの分類は不適切。",
    source: { title: "過敏性腸症候群(IBS)を見抜くポイントと専門医紹介のタイミング（田中由佳里, medicina 63巻8号, 2026）", url: "https://webview.isho.jp/journal/detail/abs/10.11477/mf.002576990630081156" },
    tags: ["IBS", "過敏性腸症候群", "Rome IV基準", "Bristol便形状スケール", "PI-IBS", "消化器・肝"]
