    explanation: "【要点】胃内視鏡・胃X線検査は死亡率減少の観察研究エビデンスがあり、推奨グレードB(証拠のレベル2＋)で対策型検診として推奨される。\n【背景/エビデンス】内視鏡検査は対象年齢50歳以上が望ましく、2〜3年間隔での実施が可能とされる。ペプシノゲン・ピロリ抗体・ABC法はリスク層別化は可能だが死亡率減少効果を示した研究がなく推奨Ⅰで、用いる場合は内視鏡などへの連携が前提となる。\n【臨床応用/注意】ピロリ除菌は胃がん発症抑制に有効だが、除菌後も年齢・萎縮に応じた内視鏡フォローを続ける。\n【誤答】ABC法単独の対策型推奨や、除菌効果の否定・フォロー不要とする記述は本稿と整合しない。",
    source: { title: "胃がん検診について教えてください（渡邊清高, 診断と治療 114巻13号, 2026）", url: "https://webview.isho.jp/journal/detail/abs/10.34433/dt.0000001726" },
