    options: ["診断は右下腹部の限局性圧痛のみで確定でき、スコアリングや画像検査は不要である", "単純性(非穿孔性)虫垂炎では、緊急手術をせずに抗菌薬で治療する非切除治療(NOM)が選択肢となる", "膿瘍形成例や発症から日数が経過した例では、抗菌薬で炎症を鎮めたのちに待機的切除(interval appendectomy)を行う選択肢がある", "NOM後の再発(90日で約3割)や40歳以上での虫垂腫瘍を念頭に、増悪時の緊急手術や外科コンサルトを想定する"],
