    explanation: "【要点】急性虫垂炎の診断は症状・身体所見・血液検査の炎症値をスコア化し、CTなどの画像を加えて精度を高める。虫垂位置の個体差で所見は多様となる。\n【背景/エビデンス】単純性虫垂炎は抗菌薬による非切除治療(NOM)が可能で、膿瘍形成例や発症から日数が経過した例ではinterval appendectomy(待機的切除)も選択肢となる。\n【臨床応用/注意】NOM後90日で約3割が再発し、40歳以上では虫垂腫瘍が隠れうるため、増悪時の緊急手術を想定し、可能なら診断時に外科へコンサルトする。\n【誤答】限局性圧痛のみでの確定やスコア・画像の省略は診断精度を欠き不適切である。",
    source: { title: "成人の急性虫垂炎—外科医からお伝えしたい最新事情（里吉哲太, medicina 63巻8号, 2026）", url: "https://webview.isho.jp/journal/detail/abs/10.11477/mf.002576990630081182" },
