    options: ["血中好酸球高値例に限って増悪抑制効果が示された", "最適化された吸入維持療法への上乗せで増悪率に有意差は認めなかった", "血中好酸球数によらず、最適化吸入療法への上乗せで増悪を抑制する効果が示された", "既存の抗IL-5系生物学的製剤に対する優越性が直接比較で確立した"],
