    explanation: "【要点】動作緩慢ではまず発症様式・左右差・随伴症状・内服歴を確認し、薬剤性パーキンソニズムを除外することが出発点となる。\n【背景/エビデンス】動作緩慢は運動緩慢・運動減少・シークエンス効果・タイミングの不規則さ・無動・寡動からなる「動作緩慢複合」として捉える。緩徐進行性で左右差やシークエンス効果を伴えばParkinson病を疑い脳神経内科紹介を検討する。\n【臨床応用/注意】急性・亜急性発症では血管性・代謝性・薬剤性を優先し、筋力低下主体なら筋疾患、意欲・認知低下が前景ならうつ病や認知症を鑑別する。\n【誤答】急性発症でまず神経変性疾患を考える、単一症候として評価する、左右差ある緩徐進行でPDを否定する対応はいずれも不適切。",
