    options: ["冷却より先に解熱薬(アセトアミノフェンなど)の投与を優先する", "重症度にかかわらず、速やかな積極的冷却(active cooling)を治療の中心に据える", "労作性熱中症では氷水浸漬(cold water immersion)による冷却が推奨される", "意識障害を伴う重症例では冷却は行わず、輸液のみで経過をみる"],
    correct: [1, 2],
    explanation: "【要点】重症熱中症では重症度にかかわらず速やかな積極的冷却(active cooling)が治療の中心で、労作性では氷水浸漬が有効である。\n【背景/エビデンス】熱中症の予後は高体温の持続時間に依存するため、診断と並行して直ちに冷却を開始する。労作性熱中症ではcold water immersionが最も速く深部体温を低下させる。目標体温付近(概ね38℃台)ではオーバーシュートによる低体温を避けるよう冷却を調整する。\n【臨床応用/注意】輸液や臓器障害への集学的治療を併用し、深部体温・意識・循環を継続監視する。\n【誤答】解熱薬は熱中症の体温上昇機序に無効で優先されない。意識障害を伴う重症例で冷却を行わず輸液のみとする対応も不適切。",
    source: { title: "熱中症：重症度にかかわらず，Active Coolingは集学的治療の中心を占める（神田潤, Hospitalist 13巻2号, 2026）", url: "https://webview.isho.jp/journal/detail/abs/10.11477/mf.218804090130020223" },
    tags: ["熱中症", "積極的冷却", "氷水浸漬", "救急", "その他"]
